select rx.person_id, rx.drug_exposure_start_date,
  CASE
    WHEN rx.days_per_unit IS NOT NULL THEN COALESCE(
      DATEADD(day, rx.quantity * rx.days_per_unit - 1, rx.drug_exposure_start_date),
      DATEADD(day, rx.days_supply, rx.drug_exposure_start_date),
      DATEADD(day, 1, rx.drug_exposure_start_date)
    )
    ELSE COALESCE(
      rx.drug_exposure_end_date,
      DATEADD(day, rx.days_supply, rx.drug_exposure_start_date),
      DATEADD(day, 1, rx.drug_exposure_start_date)
    )
  END as drug_exposure_end_date
